const getRootModel = (mesh: BABYLON.AbstractMesh): BABYLON.AbstractMesh => {
  let curr: BABYLON.Node | null = mesh;
  let topValid: BABYLON.AbstractMesh = mesh;
  while (curr && curr.parent) {
    curr = curr.parent;
